def strip_whitespace(apps, schema_editor):
    """
    remove leading/trailing whitespace from the taxa of the faunal results (the upload strips them from now on)
    """
    FaunalResults = apps.get_model("main", "FaunalResults")
    for field in ["order", "family", "scientific_name", "taxid"]:
        for pk, value in FaunalResults.objects.exclude(**{field: None}).values_list("pk", field):
            if value != value.strip():
                FaunalResults.objects.filter(pk=pk).update(**{field: value.strip()})


